{
  "name": "Orbital Sphere Visualization",
  "description": "A high-performance interactive 3D sphere visualization with multiple orbits and floating labels using Canvas 2D and perspective projection.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface OrbitConfig {
  radius: number;
  normal: Point3D; // Normal vector defining the plane of the orbit
  u: Point3D;      // Basis vector 1
  v: Point3D;      // Basis vector 2
}

export interface Label {
  text: string;
  orbitIndex: number;
  t: number;      // Current position on orbit (0 to 1)
  speed: number;  // Rotation speed
}

export interface SimulationSettings {
  backgroundColor: string;
  orbitCount: number;
  sphereRadius: number;
  fov: number;
  dashStyle: number[];
  minLabelSpeed: number;
  maxLabelSpeed: number;
  labelTiltEnabled: boolean;
  opacityRange: [number, number]; // [minAlpha, maxAlpha]
}

import { SimulationSettings } from './types';

export const SETTINGS: SimulationSettings = {
  backgroundColor: '#182432',
  orbitCount: 8,
  sphereRadius: 200,
  fov: 800,
  dashStyle: [2, 4],
  minLabelSpeed: 0.0005,
  maxLabelSpeed: 0.002,
  labelTiltEnabled: false, // Easily toggleable tilt option
  opacityRange: [0.2, 0.8],
};

export const LABELS = [
  'Klik', 'Ninehire', '긱몬', 'Loop AI', 'Jobkorea', 
  'Bossmon', 'Jobplanet', 'Nooc', 'Gamejob', 'Albamon'
];

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { SETTINGS, LABELS } from './constants';
import { Point3D, OrbitConfig, Label } from './types';

/**
 * Utility: Normalize a 3D vector
 */
const normalize = (p: Point3D): Point3D => {
  const mag = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
  return { x: p.x / mag, y: p.y / mag, z: p.z / mag };
};

/**
 * Utility: Vector cross product
 */
const cross = (a: Point3D, b: Point3D): Point3D => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const orbitsRef = useRef<OrbitConfig[]>([]);
  const labelsRef = useRef<Label[]>([]);
  const mouseRef = useRef({ x: 0, y: 0, targetX: 0, targetY: 0 });
  const frameIdRef = useRef<number>(0);

  // Initialize Orbits and Labels
  const initSimulation = useCallback(() => {
    const orbits: OrbitConfig[] = [];
    const sphereRadius = SETTINGS.sphereRadius;

    for (let i = 0; i < SETTINGS.orbitCount; i++) {
      // Create random normal vector for orbit plane
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const normal = normalize({
        x: Math.sin(phi) * Math.cos(theta),
        y: Math.sin(phi) * Math.sin(theta),
        z: Math.cos(phi),
      });

      // Find basis vectors u, v for the plane
      let temp = { x: 1, y: 0, z: 0 };
      if (Math.abs(normal.x) > 0.9) temp = { x: 0, y: 1, z: 0 };
      const u = normalize(cross(normal, temp));
      const v = cross(normal, u);

      orbits.push({
        radius: sphereRadius + (Math.random() * 20 - 10), // slight variation in radius
        normal,
        u,
        v,
      });
    }
    orbitsRef.current = orbits;

    const labels: Label[] = LABELS.map((text, idx) => ({
      text,
      orbitIndex: idx % orbits.length,
      t: Math.random(),
      speed: SETTINGS.minLabelSpeed + Math.random() * (SETTINGS.maxLabelSpeed - SETTINGS.minLabelSpeed),
    }));
    labelsRef.current = labels;
  }, []);

  // Handle Resize
  const handleResize = useCallback(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
  }, []);

  // Handle Mouse Move for Parallax
  const handleMouseMove = (e: MouseEvent) => {
    mouseRef.current.targetX = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2);
    mouseRef.current.targetY = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2);
  };

  useEffect(() => {
    initSimulation();
    handleResize();
    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / 2;
      const centerY = height / 2;

      // Smooth mouse movement
      mouseRef.current.x += (mouseRef.current.targetX - mouseRef.current.x) * 0.05;
      mouseRef.current.y += (mouseRef.current.targetY - mouseRef.current.y) * 0.05;

      ctx.clearRect(0, 0, width, height);
      ctx.save();
      ctx.scale(dpr, dpr);

      // Camera rotation based on mouse
      const rotX = mouseRef.current.y * 0.2; // Max 0.2 rad tilt
      const rotY = mouseRef.current.x * 0.2;

      const project = (p: Point3D): { x: number; y: number; z: number; scale: number } => {
        // Apply rotation
        // Y-axis rotation
        let x = p.x * Math.cos(rotY) + p.z * Math.sin(rotY);
        let z = -p.x * Math.sin(rotY) + p.z * Math.cos(rotY);
        // X-axis rotation
        let y = p.y * Math.cos(rotX) - z * Math.sin(rotX);
        z = p.y * Math.sin(rotX) + z * Math.cos(rotX);

        const scale = SETTINGS.fov / (SETTINGS.fov + z);
        return {
          x: (width / dpr / 2) + x * scale,
          y: (height / dpr / 2) + y * scale,
          z,
          scale,
        };
      };

      // Draw Sequence: Back-half orbits -> Sphere -> Front-half orbits -> Labels
      // To simplify, we'll draw based on Z sorting or split the orbit loops.

      // Pre-calculate positions for all labels
      const processedLabels = labelsRef.current.map((label) => {
        const orbit = orbitsRef.current[label.orbitIndex];
        const angle = label.t * Math.PI * 2;
        const p3d: Point3D = {
          x: orbit.radius * (Math.cos(angle) * orbit.u.x + Math.sin(angle) * orbit.v.x),
          y: orbit.radius * (Math.cos(angle) * orbit.u.y + Math.sin(angle) * orbit.v.y),
          z: orbit.radius * (Math.cos(angle) * orbit.u.z + Math.sin(angle) * orbit.v.z),
        };
        const proj = project(p3d);

        // Calculate tangent for tilt if enabled
        let tilt = 0;
        if (SETTINGS.labelTiltEnabled) {
            const nextAngle = (label.t + 0.01) * Math.PI * 2;
            const nextP3d = {
                x: orbit.radius * (Math.cos(nextAngle) * orbit.u.x + Math.sin(nextAngle) * orbit.v.x),
                y: orbit.radius * (Math.cos(nextAngle) * orbit.u.y + Math.sin(nextAngle) * orbit.v.y),
                z: orbit.radius * (Math.cos(nextAngle) * orbit.u.z + Math.sin(nextAngle) * orbit.v.z),
            };
            const nextProj = project(nextP3d);
            tilt = Math.atan2(nextProj.y - proj.y, nextProj.x - proj.x);
        }

        label.t = (label.t + label.speed) % 1;
        return { ...label, ...proj, tilt };
      });

      // Draw orbits back-to-front by segmenting or just using Z-sort for simplicity
      // For performance and clarity, we'll draw the whole orbit with variable alpha based on Z

      const drawOrbit = (orbit: OrbitConfig) => {
        ctx.beginPath();
        ctx.setLineDash(SETTINGS.dashStyle);
        const steps = 64;
        for (let j = 0; j <= steps; j++) {
          const angle = (j / steps) * Math.PI * 2;
          const p3d = {
            x: orbit.radius * (Math.cos(angle) * orbit.u.x + Math.sin(angle) * orbit.v.x),
            y: orbit.radius * (Math.cos(angle) * orbit.u.y + Math.sin(angle) * orbit.v.y),
            z: orbit.radius * (Math.cos(angle) * orbit.u.z + Math.sin(angle) * orbit.v.z),
          };
          const proj = project(p3d);

          const zNorm = (proj.z + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
          const alpha = SETTINGS.opacityRange[1] - (zNorm * (SETTINGS.opacityRange[1] - SETTINGS.opacityRange[0]));

          ctx.strokeStyle = `rgba(220, 230, 255, ${Math.max(0, alpha)})`;
          ctx.lineWidth = 1 * proj.scale;

          if (j === 0) ctx.moveTo(proj.x, proj.y);
          else {
            // We need to stroke segments to vary color/width
            ctx.lineTo(proj.x, proj.y);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(proj.x, proj.y);
          }
        }
      };

      // 1. Draw back labels (z > 0)
      processedLabels.filter(l => l.z > 0).forEach(label => drawLabel(ctx, label));

      // 2. Draw central sphere
      drawSphere(ctx, (width / dpr / 2), (height / dpr / 2), SETTINGS.sphereRadius);

      // 3. Draw orbits (we draw them after sphere with transparency for a layering effect)
      orbitsRef.current.forEach(drawOrbit);

      // 4. Draw front labels (z <= 0)
      processedLabels.filter(l => l.z <= 0).forEach(label => drawLabel(ctx, label));

      ctx.restore();
      frameIdRef.current = requestAnimationFrame(animate);
    };

    const drawSphere = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number) => {
      ctx.save();
      const grad = ctx.createRadialGradient(x - r*0.3, y - r*0.3, r * 0.1, x, y, r);
      grad.addColorStop(0, 'rgba(255, 255, 255, 0.08)');
      grad.addColorStop(0.5, 'rgba(100, 150, 255, 0.03)');
      grad.addColorStop(1, 'rgba(0, 20, 40, 0.1)');

      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Subtle rim
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 0.5;
      ctx.stroke();
      ctx.restore();
    };

    const drawLabel = (ctx: CanvasRenderingContext2D, label: any) => {
      const zNorm = (label.z + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
      const alpha = 1.0 - (zNorm * 0.7); // Labels fade more in back
      const sizeScale = label.scale * 0.9;

      ctx.save();
      ctx.translate(label.x, label.y);
      if (SETTINGS.labelTiltEnabled) {
          ctx.rotate(label.tilt);
      }

      ctx.font = `${Math.floor(14 * sizeScale)}px Inter, system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // Background glow for text
      ctx.shadowBlur = 4;
      ctx.shadowColor = `rgba(255, 255, 255, ${alpha * 0.3})`;

      ctx.fillStyle = `rgba(255, 255, 255, ${Math.max(0.1, alpha)})`;
      ctx.fillText(label.text, 0, 0);
      ctx.restore();
    };

    frameIdRef.current = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(frameIdRef.current);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [initSimulation, handleResize]);

  return (
    <div className="relative w-full h-full bg-[#182432] overflow-hidden flex items-center justify-center">
      <canvas ref={canvasRef} className="absolute inset-0 pointer-events-none" />

      {/* Configuration Legend Overlay */}
      <div className="absolute bottom-6 left-6 text-white/30 text-xs font-mono select-none pointer-events-none">
        <p>ORBITS: {SETTINGS.orbitCount}</p>
        <p>RADIUS: {SETTINGS.sphereRadius}px</p>
        <p>INTERACTION: MOUSE PARALLAX</p>
      </div>

      {/* Decorative center point */}
      <div className="w-1 h-1 bg-white/20 rounded-full blur-[1px]"></div>
    </div>
  );
};

export default App;

import { SimulationSettings } from './types';

export const SETTINGS: SimulationSettings & { autoRotateSpeed: number } = {
  backgroundColor: '#182432',
  orbitCount: 8,
  sphereRadius: 260, // Slightly larger to match the image scale
  fov: 1000,
  dashStyle: [1, 3], // Finer dots to match the reference image
  minLabelSpeed: 0.0003,
  maxLabelSpeed: 0.001,
  labelTiltEnabled: false,
  opacityRange: [0.15, 0.7], // More contrast between front and back
  autoRotateSpeed: 0.002, // Automatic rotation speed
};

export const LABELS = [
  'Klik', 'Ninehire', '긱몬', 'Loop AI', 'Jobkorea', 
  'Bossmon', 'Jobplanet', 'Nooc', 'Gamejob', 'Albamon'
];

import React, { useEffect, useRef, useCallback } from 'react';
import { SETTINGS, LABELS } from './constants';
import { Point3D, OrbitConfig, Label } from './types';

/**
 * Utility: Normalize a 3D vector
 */
const normalize = (p: Point3D): Point3D => {
  const mag = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
  return { x: p.x / mag, y: p.y / mag, z: p.z / mag };
};

/**
 * Utility: Vector cross product
 */
const cross = (a: Point3D, b: Point3D): Point3D => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const orbitsRef = useRef<OrbitConfig[]>([]);
  const labelsRef = useRef<Label[]>([]);
  const mouseRef = useRef({ x: 0, y: 0, targetX: 0, targetY: 0 });
  const rotationRef = useRef({ x: 0, y: 0 }); // Tracks automatic rotation
  const frameIdRef = useRef<number>(0);

  // Initialize Orbits and Labels
  const initSimulation = useCallback(() => {
    const orbits: OrbitConfig[] = [];
    const sphereRadius = SETTINGS.sphereRadius;

    for (let i = 0; i < SETTINGS.orbitCount; i++) {
      // Create random normal vector for orbit plane
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const normal = normalize({
        x: Math.sin(phi) * Math.cos(theta),
        y: Math.sin(phi) * Math.sin(theta),
        z: Math.cos(phi),
      });

      // Find basis vectors u, v for the plane
      let temp = { x: 1, y: 0, z: 0 };
      if (Math.abs(normal.x) > 0.9) temp = { x: 0, y: 1, z: 0 };
      const u = normalize(cross(normal, temp));
      const v = cross(normal, u);

      orbits.push({
        radius: sphereRadius + (Math.random() * 10 - 5), // Tight fit around sphere
        normal,
        u,
        v,
      });
    }
    orbitsRef.current = orbits;

    const labels: Label[] = LABELS.map((text, idx) => ({
      text,
      orbitIndex: idx % orbits.length,
      t: Math.random(),
      speed: SETTINGS.minLabelSpeed + Math.random() * (SETTINGS.maxLabelSpeed - SETTINGS.minLabelSpeed),
    }));
    labelsRef.current = labels;
  }, []);

  const handleResize = useCallback(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
  }, []);

  const handleMouseMove = (e: MouseEvent) => {
    mouseRef.current.targetX = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2);
    mouseRef.current.targetY = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2);
  };

  useEffect(() => {
    initSimulation();
    handleResize();
    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / (dpr * 2);
      const centerY = height / (dpr * 2);

      // 1. Update Auto Rotation and Mouse Parallax
      rotationRef.current.y += SETTINGS.autoRotateSpeed;
      rotationRef.current.x += SETTINGS.autoRotateSpeed * 0.3; // Slight pitch variation

      mouseRef.current.x += (mouseRef.current.targetX - mouseRef.current.x) * 0.05;
      mouseRef.current.y += (mouseRef.current.targetY - mouseRef.current.y) * 0.05;

      const currentRotY = rotationRef.current.y + mouseRef.current.x * 0.15;
      const currentRotX = rotationRef.current.x + mouseRef.current.y * 0.15;

      ctx.clearRect(0, 0, width, height);
      ctx.save();
      ctx.scale(dpr, dpr);

      // Project function combining auto-rot + mouse parallax
      const project = (p: Point3D): { x: number; y: number; z: number; scale: number } => {
        // Y-axis rotation
        let x = p.x * Math.cos(currentRotY) + p.z * Math.sin(currentRotY);
        let z = -p.x * Math.sin(currentRotY) + p.z * Math.cos(currentRotY);
        // X-axis rotation
        let y = p.y * Math.cos(currentRotX) - z * Math.sin(currentRotX);
        z = p.y * Math.sin(currentRotX) + z * Math.cos(currentRotX);

        const scale = SETTINGS.fov / (SETTINGS.fov + z);
        return {
          x: centerX + x * scale,
          y: centerY + y * scale,
          z,
          scale,
        };
      };

      // 2. Pre-calculate label positions
      const processedLabels = labelsRef.current.map((label) => {
        const orbit = orbitsRef.current[label.orbitIndex];
        const angle = label.t * Math.PI * 2;
        const p3d: Point3D = {
          x: orbit.radius * (Math.cos(angle) * orbit.u.x + Math.sin(angle) * orbit.v.x),
          y: orbit.radius * (Math.cos(angle) * orbit.u.y + Math.sin(angle) * orbit.v.y),
          z: orbit.radius * (Math.cos(angle) * orbit.u.z + Math.sin(angle) * orbit.v.z),
        };
        const proj = project(p3d);
        label.t = (label.t + label.speed) % 1;
        return { ...label, ...proj };
      });

      // 3. Draw Back Orbits (Segmented for Z depth)
      const drawOrbits = (isFront: boolean) => {
        ctx.setLineDash(SETTINGS.dashStyle);
        orbitsRef.current.forEach((orbit) => {
          const steps = 120; // High resolution for smooth curves
          for (let j = 0; j < steps; j++) {
            const angle1 = (j / steps) * Math.PI * 2;
            const angle2 = ((j + 1) / steps) * Math.PI * 2;

            const p1 = {
              x: orbit.radius * (Math.cos(angle1) * orbit.u.x + Math.sin(angle1) * orbit.v.x),
              y: orbit.radius * (Math.cos(angle1) * orbit.u.y + Math.sin(angle1) * orbit.v.y),
              z: orbit.radius * (Math.cos(angle1) * orbit.u.z + Math.sin(angle1) * orbit.v.z),
            };
            const p2 = {
              x: orbit.radius * (Math.cos(angle2) * orbit.u.x + Math.sin(angle2) * orbit.v.x),
              y: orbit.radius * (Math.cos(angle2) * orbit.u.y + Math.sin(angle2) * orbit.v.y),
              z: orbit.radius * (Math.cos(angle2) * orbit.u.z + Math.sin(angle2) * orbit.v.z),
            };

            const proj1 = project(p1);
            const proj2 = project(p2);

            // Determine if segment is front or back
            const isSegmentFront = proj1.z < 0 && proj2.z < 0;
            if (isFront !== isSegmentFront) continue;

            const zNorm = (proj1.z + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
            const alpha = SETTINGS.opacityRange[1] - (zNorm * (SETTINGS.opacityRange[1] - SETTINGS.opacityRange[0]));

            ctx.beginPath();
            ctx.strokeStyle = `rgba(220, 235, 255, ${Math.max(0.05, alpha)})`;
            ctx.lineWidth = 0.8 * proj1.scale;
            ctx.moveTo(proj1.x, proj1.y);
            ctx.lineTo(proj2.x, proj2.y);
            ctx.stroke();
          }
        });
      };

      // Depth Layer Rendering:
      // 1. Back Orbits
      drawOrbits(false);
      // 2. Back Labels
      processedLabels.filter(l => l.z > 0).forEach(l => drawLabel(ctx, l));
      // 3. Central Sphere
      drawSphere(ctx, centerX, centerY, SETTINGS.sphereRadius);
      // 4. Front Orbits
      drawOrbits(true);
      // 5. Front Labels
      processedLabels.filter(l => l.z <= 0).forEach(l => drawLabel(ctx, l));

      ctx.restore();
      frameIdRef.current = requestAnimationFrame(animate);
    };

    const drawSphere = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number) => {
      ctx.save();
      // Outer Boundary
      const grad = ctx.createRadialGradient(x, y, r * 0.4, x, y, r);
      grad.addColorStop(0, 'rgba(40, 60, 90, 0.05)');
      grad.addColorStop(0.7, 'rgba(100, 140, 180, 0.08)');
      grad.addColorStop(1, 'rgba(150, 180, 255, 0.02)');

      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Subtle rim light
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
      ctx.lineWidth = 1;
      ctx.stroke();

      // Vignette effect to give volume
      const vignette = ctx.createRadialGradient(x, y, r * 0.8, x, y, r);
      vignette.addColorStop(0, 'rgba(24, 36, 50, 0)');
      vignette.addColorStop(1, 'rgba(10, 20, 30, 0.3)');
      ctx.fillStyle = vignette;
      ctx.fill();

      ctx.restore();
    };

    const drawLabel = (ctx: CanvasRenderingContext2D, label: any) => {
      const zNorm = (label.z + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
      // More aggressive opacity drop-off for labels "behind" the sphere
      const alpha = label.z > 0 ? 0.3 : 1.0; 
      const sizeScale = label.scale * (label.z > 0 ? 0.85 : 1.0);

      ctx.save();
      ctx.translate(label.x, label.y);

      // Bold/Clean font for labels
      ctx.font = `600 ${Math.floor(13 * sizeScale)}px Inter, system-ui, -apple-system, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // Crisp white text with very subtle drop shadow for readability
      ctx.shadowBlur = 2;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';

      ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
      ctx.fillText(label.text, 0, 0);
      ctx.restore();
    };

    frameIdRef.current = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(frameIdRef.current);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [initSimulation, handleResize]);

  return (
    <div className="relative w-full h-full bg-[#182432] overflow-hidden flex items-center justify-center">
      <canvas ref={canvasRef} className="absolute inset-0" />

      {/* Visual center anchor to match reference image detail */}
      <div className="w-[3px] h-[3px] bg-blue-600 rounded-sm opacity-50"></div>
    </div>
  );
};

export default App;

import { SimulationSettings } from './types';

export const SETTINGS: SimulationSettings & { autoRotateSpeed: number; dashOffsetSpeed: number } = {
  backgroundColor: '#182432',
  orbitCount: 4, // Exactly 4 orbits as requested
  sphereRadius: 280, 
  fov: 1000,
  dashStyle: [1, 3], // Fine dots matching reference
  minLabelSpeed: 0.0003,
  maxLabelSpeed: 0.001,
  labelTiltEnabled: false,
  opacityRange: [0.2, 0.8],
  autoRotateSpeed: 0.0015, 
  dashOffsetSpeed: 0.2, // Speed at which dots move along the line
};

export const LABELS = [
  'Klik', 'Ninehire', '긱몬', 'Loop AI', 'Jobkorea', 
  'Bossmon', 'Jobplanet', 'Nooc', 'Gamejob', 'Albamon'
];

import React, { useEffect, useRef, useCallback } from 'react';
import { SETTINGS, LABELS } from './constants';
import { Point3D, OrbitConfig, Label } from './types';

/**
 * Utility: Normalize a 3D vector
 */
const normalize = (p: Point3D): Point3D => {
  const mag = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
  return { x: p.x / mag, y: p.y / mag, z: p.z / mag };
};

/**
 * Utility: Vector cross product
 */
const cross = (a: Point3D, b: Point3D): Point3D => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const orbitsRef = useRef<OrbitConfig[]>([]);
  const labelsRef = useRef<Label[]>([]);
  const mouseRef = useRef({ x: 0, y: 0, targetX: 0, targetY: 0 });
  const rotationRef = useRef({ x: 0, y: 0 }); 
  const dashOffsetRef = useRef(0);
  const frameIdRef = useRef<number>(0);

  // Initialize Orbits and Labels
  const initSimulation = useCallback(() => {
    const orbits: OrbitConfig[] = [];
    const sphereRadius = SETTINGS.sphereRadius;

    for (let i = 0; i < SETTINGS.orbitCount; i++) {
      // Create random normal vector for orbit plane
      const theta = (i / SETTINGS.orbitCount) * Math.PI * 2; // Distribute planes somewhat evenly
      const phi = Math.random() * Math.PI;
      const normal = normalize({
        x: Math.sin(phi) * Math.cos(theta),
        y: Math.sin(phi) * Math.sin(theta),
        z: Math.cos(phi),
      });

      // Find basis vectors u, v for the plane
      let temp = { x: 1, y: 0, z: 0 };
      if (Math.abs(normal.x) > 0.9) temp = { x: 0, y: 1, z: 0 };
      const u = normalize(cross(normal, temp));
      const v = cross(normal, u);

      orbits.push({
        radius: sphereRadius, // Must be exactly flush with the sphere
        normal,
        u,
        v,
      });
    }
    orbitsRef.current = orbits;

    const labels: Label[] = LABELS.map((text, idx) => ({
      text,
      orbitIndex: idx % orbits.length,
      t: Math.random(),
      speed: SETTINGS.minLabelSpeed + Math.random() * (SETTINGS.maxLabelSpeed - SETTINGS.minLabelSpeed),
    }));
    labelsRef.current = labels;
  }, []);

  const handleResize = useCallback(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
  }, []);

  const handleMouseMove = (e: MouseEvent) => {
    mouseRef.current.targetX = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2);
    mouseRef.current.targetY = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2);
  };

  useEffect(() => {
    initSimulation();
    handleResize();
    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = () => {
      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / (dpr * 2);
      const centerY = height / (dpr * 2);

      // 1. Update Animations
      rotationRef.current.y += SETTINGS.autoRotateSpeed;
      rotationRef.current.x += SETTINGS.autoRotateSpeed * 0.2;
      dashOffsetRef.current -= SETTINGS.dashOffsetSpeed; // Move dots along path

      mouseRef.current.x += (mouseRef.current.targetX - mouseRef.current.x) * 0.05;
      mouseRef.current.y += (mouseRef.current.targetY - mouseRef.current.y) * 0.05;

      const currentRotY = rotationRef.current.y + mouseRef.current.x * 0.15;
      const currentRotX = rotationRef.current.x + mouseRef.current.y * 0.15;

      ctx.clearRect(0, 0, width, height);
      ctx.save();
      ctx.scale(dpr, dpr);

      const project = (p: Point3D): { x: number; y: number; z: number; scale: number } => {
        let x = p.x * Math.cos(currentRotY) + p.z * Math.sin(currentRotY);
        let z = -p.x * Math.sin(currentRotY) + p.z * Math.cos(currentRotY);
        let y = p.y * Math.cos(currentRotX) - z * Math.sin(currentRotX);
        z = p.y * Math.sin(currentRotX) + z * Math.cos(currentRotX);

        const scale = SETTINGS.fov / (SETTINGS.fov + z);
        return {
          x: centerX + x * scale,
          y: centerY + y * scale,
          z,
          scale,
        };
      };

      // 2. Process Labels
      const processedLabels = labelsRef.current.map((label) => {
        const orbit = orbitsRef.current[label.orbitIndex];
        const angle = label.t * Math.PI * 2;
        const p3d: Point3D = {
          x: orbit.radius * (Math.cos(angle) * orbit.u.x + Math.sin(angle) * orbit.v.x),
          y: orbit.radius * (Math.cos(angle) * orbit.u.y + Math.sin(angle) * orbit.v.y),
          z: orbit.radius * (Math.cos(angle) * orbit.u.z + Math.sin(angle) * orbit.v.z),
        };
        const proj = project(p3d);
        label.t = (label.t + label.speed) % 1;
        return { ...label, ...proj };
      });

      // 3. Draw Orbit Segments (Back vs Front)
      const drawOrbits = (isFront: boolean) => {
        ctx.setLineDash(SETTINGS.dashStyle);
        ctx.lineDashOffset = dashOffsetRef.current;

        orbitsRef.current.forEach((orbit) => {
          const steps = 120;
          for (let j = 0; j < steps; j++) {
            const angle1 = (j / steps) * Math.PI * 2;
            const angle2 = ((j + 1) / steps) * Math.PI * 2;

            const p1 = {
              x: orbit.radius * (Math.cos(angle1) * orbit.u.x + Math.sin(angle1) * orbit.v.x),
              y: orbit.radius * (Math.cos(angle1) * orbit.u.y + Math.sin(angle1) * orbit.v.y),
              z: orbit.radius * (Math.cos(angle1) * orbit.u.z + Math.sin(angle1) * orbit.v.z),
            };
            const p2 = {
              x: orbit.radius * (Math.cos(angle2) * orbit.u.x + Math.sin(angle2) * orbit.v.x),
              y: orbit.radius * (Math.cos(angle2) * orbit.u.y + Math.sin(angle2) * orbit.v.y),
              z: orbit.radius * (Math.cos(angle2) * orbit.u.z + Math.sin(angle2) * orbit.v.z),
            };

            const proj1 = project(p1);
            const proj2 = project(p2);

            // Using the average Z of segment to determine visibility
            const avgZ = (proj1.z + proj2.z) / 2;
            const isSegmentFront = avgZ < 0;

            if (isFront !== isSegmentFront) continue;

            const zNorm = (avgZ + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
            const alpha = SETTINGS.opacityRange[1] - (zNorm * (SETTINGS.opacityRange[1] - SETTINGS.opacityRange[0]));

            ctx.beginPath();
            ctx.strokeStyle = `rgba(220, 235, 255, ${Math.max(0.1, alpha)})`;
            ctx.lineWidth = 1.0 * proj1.scale;
            ctx.moveTo(proj1.x, proj1.y);
            ctx.lineTo(proj2.x, proj2.y);
            ctx.stroke();
          }
        });
      };

      // Layered Draw:
      drawOrbits(false); // Back orbits
      processedLabels.filter(l => l.z > 0).forEach(l => drawLabel(ctx, l));
      drawSphere(ctx, centerX, centerY, SETTINGS.sphereRadius);
      drawOrbits(true); // Front orbits
      processedLabels.filter(l => l.z <= 0).forEach(l => drawLabel(ctx, l));

      ctx.restore();
      frameIdRef.current = requestAnimationFrame(animate);
    };

    const drawSphere = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number) => {
      ctx.save();
      // Main Body
      const grad = ctx.createRadialGradient(x, y, r * 0.2, x, y, r);
      grad.addColorStop(0, 'rgba(40, 60, 90, 0.05)');
      grad.addColorStop(0.8, 'rgba(80, 110, 160, 0.12)');
      grad.addColorStop(1, 'rgba(120, 160, 220, 0.05)');

      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Rim
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
      ctx.lineWidth = 1;
      ctx.stroke();

      // Soft occlusion vignette
      const vignette = ctx.createRadialGradient(x, y, r * 0.85, x, y, r);
      vignette.addColorStop(0, 'rgba(24, 36, 50, 0)');
      vignette.addColorStop(1, 'rgba(10, 15, 25, 0.25)');
      ctx.fillStyle = vignette;
      ctx.fill();

      ctx.restore();
    };

    const drawLabel = (ctx: CanvasRenderingContext2D, label: any) => {
      // Opacity depends on depth, but size stays constant
      const alpha = label.z > 0 ? 0.35 : 1.0; 

      ctx.save();
      ctx.translate(label.x, label.y);

      // FONT SIZE REMAINS CONSTANT (e.g. 14px)
      ctx.font = `600 14px Inter, system-ui, -apple-system, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // Slight shadow to help against complex background
      ctx.shadowBlur = 1;
      ctx.shadowColor = 'rgba(0,0,0,0.8)';

      ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
      ctx.fillText(label.text, 0, 0);
      ctx.restore();
    };

    frameIdRef.current = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(frameIdRef.current);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [initSimulation, handleResize]);

  return (
    <div className="relative w-full h-full bg-[#182432] overflow-hidden flex items-center justify-center">
      <canvas ref={canvasRef} className="absolute inset-0" />

      {/* Visual center anchor (the blue dot/square from the reference) */}
      <div className="w-[4px] h-[4px] bg-blue-700 rounded-sm opacity-60 relative z-10"></div>
    </div>
  );
};

export default App;

import { SimulationSettings } from './types';

export const SETTINGS: SimulationSettings & { loopDuration: number } = {
  backgroundColor: '#182432',
  orbitCount: 4, 
  sphereRadius: 280, 
  fov: 1000,
  dashStyle: [1, 3], 
  minLabelSpeed: 0.0003,
  maxLabelSpeed: 0.001,
  labelTiltEnabled: false,
  opacityRange: [0.15, 0.6],
  loopDuration: 30000, // 30 seconds in milliseconds
};

export const LABELS = [
  'Klik', 'Ninehire', '긱몬', 'Loop AI', 'Jobkorea', 
  'Bossmon', 'Jobplanet', 'Nooc', 'Gamejob', 'Albamon'
];

import React, { useEffect, useRef, useCallback } from 'react';
import { SETTINGS, LABELS } from './constants';
import { Point3D, OrbitConfig, Label } from './types';

const normalize = (p: Point3D): Point3D => {
  const mag = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
  return { x: p.x / mag, y: p.y / mag, z: p.z / mag };
};

const cross = (a: Point3D, b: Point3D): Point3D => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});

const App: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const orbitsRef = useRef<OrbitConfig[]>([]);
  const labelsRef = useRef<Label[]>([]);
  const mouseRef = useRef({ x: 0, y: 0, targetX: 0, targetY: 0 });
  const frameIdRef = useRef<number>(0);

  // Initialize Orbits with better spatial distribution
  const initSimulation = useCallback(() => {
    const orbits: OrbitConfig[] = [];
    const sphereRadius = SETTINGS.sphereRadius;

    // Fixed well-spread planes to match the reference image's balanced look
    const normals = [
      normalize({ x: 1, y: 0.2, z: 0.1 }),
      normalize({ x: 0.1, y: 1, z: 0.2 }),
      normalize({ x: -0.5, y: -0.5, z: 1 }),
      normalize({ x: 0.8, y: -0.8, z: 0.3 }),
    ];

    for (let i = 0; i < SETTINGS.orbitCount; i++) {
      const normal = normals[i % normals.length];
      let temp = { x: 1, y: 0, z: 0 };
      if (Math.abs(normal.x) > 0.9) temp = { x: 0, y: 1, z: 0 };
      const u = normalize(cross(normal, temp));
      const v = cross(normal, u);

      orbits.push({
        radius: sphereRadius,
        normal,
        u,
        v,
      });
    }
    orbitsRef.current = orbits;

    const labels: Label[] = LABELS.map((text, idx) => ({
      text,
      orbitIndex: idx % orbits.length,
      t: (idx / LABELS.length), // Evenly spaced start positions for a better loop
      speed: 1, // Normalized speed for time-based animation
    }));
    labelsRef.current = labels;
  }, []);

  const handleResize = useCallback(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
  }, []);

  const handleMouseMove = (e: MouseEvent) => {
    mouseRef.current.targetX = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2);
    mouseRef.current.targetY = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2);
  };

  useEffect(() => {
    initSimulation();
    handleResize();
    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const animate = (time: number) => {
      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width;
      const height = canvas.height;
      const centerX = width / (dpr * 2);
      const centerY = height / (dpr * 2);

      // --- 30 SECOND LOOP CALCULATION ---
      const loopTime = time % SETTINGS.loopDuration;
      const progress = loopTime / SETTINGS.loopDuration; // 0 to 1

      // Global rotation (1 full turn per loop)
      const autoRotY = progress * Math.PI * 2;
      const autoRotX = Math.sin(progress * Math.PI * 2) * 0.2; // Gentle oscillation

      // Dash offset loop (must be multiple of pattern length)
      const patternLength = SETTINGS.dashStyle[0] + SETTINGS.dashStyle[1];
      const dashOffset = progress * 100 * patternLength;

      // Mouse parallax (smooth)
      mouseRef.current.x += (mouseRef.current.targetX - mouseRef.current.x) * 0.05;
      mouseRef.current.y += (mouseRef.current.targetY - mouseRef.current.y) * 0.05;

      const rotY = autoRotY + mouseRef.current.x * 0.15;
      const rotX = autoRotX + mouseRef.current.y * 0.15;

      ctx.clearRect(0, 0, width, height);
      ctx.save();
      ctx.scale(dpr, dpr);

      const project = (p: Point3D): { x: number; y: number; z: number; scale: number } => {
        let x = p.x * Math.cos(rotY) + p.z * Math.sin(rotY);
        let z = -p.x * Math.sin(rotY) + p.z * Math.cos(rotY);
        let y = p.y * Math.cos(rotX) - z * Math.sin(rotX);
        z = p.y * Math.sin(rotX) + z * Math.cos(rotX);
        const scale = SETTINGS.fov / (SETTINGS.fov + z);
        return { x: centerX + x * scale, y: centerY + y * scale, z, scale };
      };

      // Process Labels with time-based looping position
      const processedLabels = labelsRef.current.map((label, idx) => {
        const orbit = orbitsRef.current[label.orbitIndex];
        // Move labels: 1 full orbit per 30s loop
        const currentT = (label.t + progress) % 1;
        const angle = currentT * Math.PI * 2;
        const p3d = {
          x: orbit.radius * (Math.cos(angle) * orbit.u.x + Math.sin(angle) * orbit.v.x),
          y: orbit.radius * (Math.cos(angle) * orbit.u.y + Math.sin(angle) * orbit.v.y),
          z: orbit.radius * (Math.cos(angle) * orbit.u.z + Math.sin(angle) * orbit.v.z),
        };
        return { ...label, ...project(p3d) };
      });

      const drawOrbits = (isFront: boolean) => {
        ctx.setLineDash(SETTINGS.dashStyle);
        ctx.lineDashOffset = dashOffset;
        orbitsRef.current.forEach((orbit) => {
          const steps = 140;
          for (let j = 0; j < steps; j++) {
            const a1 = (j / steps) * Math.PI * 2;
            const a2 = ((j + 1) / steps) * Math.PI * 2;
            const p1 = {
              x: orbit.radius * (Math.cos(a1) * orbit.u.x + Math.sin(a1) * orbit.v.x),
              y: orbit.radius * (Math.cos(a1) * orbit.u.y + Math.sin(a1) * orbit.v.y),
              z: orbit.radius * (Math.cos(a1) * orbit.u.z + Math.sin(a1) * orbit.v.z),
            };
            const p2 = {
              x: orbit.radius * (Math.cos(a2) * orbit.u.x + Math.sin(a2) * orbit.v.x),
              y: orbit.radius * (Math.cos(a2) * orbit.u.y + Math.sin(a2) * orbit.v.y),
              z: orbit.radius * (Math.cos(a2) * orbit.u.z + Math.sin(a2) * orbit.v.z),
            };
            const proj1 = project(p1);
            const proj2 = project(p2);
            const avgZ = (proj1.z + proj2.z) / 2;
            if (isFront !== (avgZ < 0)) continue;
            const zNorm = (avgZ + SETTINGS.sphereRadius) / (2 * SETTINGS.sphereRadius);
            const alpha = SETTINGS.opacityRange[1] - (zNorm * (SETTINGS.opacityRange[1] - SETTINGS.opacityRange[0]));
            ctx.beginPath();
            ctx.strokeStyle = `rgba(220, 235, 255, ${Math.max(0.1, alpha)})`;
            ctx.lineWidth = 0.8 * proj1.scale;
            ctx.moveTo(proj1.x, proj1.y);
            ctx.lineTo(proj2.x, proj2.y);
            ctx.stroke();
          }
        });
      };

      // Layered Draw
      drawOrbits(false);
      processedLabels.filter(l => l.z > 0).forEach(l => drawLabel(ctx, l));
      drawSphere(ctx, centerX, centerY, SETTINGS.sphereRadius);
      drawOrbits(true);
      processedLabels.filter(l => l.z <= 0).forEach(l => drawLabel(ctx, l));

      ctx.restore();
      frameIdRef.current = requestAnimationFrame(animate);
    };

    const drawSphere = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number) => {
      ctx.save();
      // "Bright outside, dark inside" gradient
      const grad = ctx.createRadialGradient(x, y, r * 0.3, x, y, r);
      grad.addColorStop(0, 'rgba(15, 25, 40, 0.4)'); // Dark inner
      grad.addColorStop(0.7, 'rgba(30, 45, 65, 0.1)'); // Mid
      grad.addColorStop(1, 'rgba(100, 140, 180, 0.15)'); // Brighter outer edge

      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Clean Rim (No Blur)
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.restore();
    };

    const drawLabel = (ctx: CanvasRenderingContext2D, label: any) => {
      const alpha = label.z > 0 ? 0.3 : 1.0; 
      ctx.save();
      ctx.translate(label.x, label.y);
      // Smaller font size as requested (11px)
      ctx.font = `600 11px Inter, system-ui, -apple-system, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      // High contrast for readability on dark backgrounds
      ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
      ctx.fillText(label.text, 0, 0);
      ctx.restore();
    };

    frameIdRef.current = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(frameIdRef.current);
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [initSimulation, handleResize]);

  return (
    <div className="relative w-full h-full bg-[#182432] overflow-hidden flex items-center justify-center">
      <canvas ref={canvasRef} className="absolute inset-0" />
      {/* Visual center anchor (the blue square) */}
      <div className="w-[3px] h-[3px] bg-blue-600 rounded-sm opacity-60 relative z-10"></div>
    </div>
  );
};

export default App;

