    // Defined 5 well-spread planes for a balanced 3D look
    const normals = [
      normalize({ x: 1, y: 0.2, z: 0.1 }),
      normalize({ x: 0.1, y: 1, z: 0.2 }),
      normalize({ x: -0.5, y: -0.5, z: 1 }),
      normalize({ x: 0.8, y: -0.8, z: 0.3 }),
      normalize({ x: -0.2, y: 0.7, z: -0.6 }), // Added 5th normal
    ];

