      ctx.save();
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = '#182432';
      ctx.globalAlpha = scale; // Fade in sphere background
      ctx.fill();
      ctx.restore();
    };

    const drawSphereSurface = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number, scale: number) => {
      if (scale <= 0) return;
      ctx.save();
