      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(24, 36, 50, ${0.2 * scale})`; 
      ctx.fill();

      const grad = ctx.createRadialGradient(x, y, r * 0.3, x, y, r);
      grad.addColorStop(0, 'rgba(24, 36, 50, 0)'); 
      grad.addColorStop(0.8, `rgba(50, 75, 100, ${0.15 * scale})`); 
      grad.addColorStop(1, `rgba(150, 190, 230, ${0.25 * scale})`); 

      ctx.fillStyle = grad;
      ctx.fill();

      ctx.strokeStyle = `rgba(255, 255, 255, ${0.12 * scale})`;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.restore();
    };

    const drawLabel = (ctx: CanvasRenderingContext2D, label: any) => {
      const depthAlpha = label.z > 0 ? 0.35 : 1.0; 
      const finalAlpha = depthAlpha * label.appearAlpha;

      const baseFontSize = 13;
